import { type ReactNode, forwardRef } from 'react'
import { type SpaceTokens, type TamaguiElement, View, type ViewProps } from 'tamagui'
import { spaceValue } from './autoGridColumns'

export interface AutoGridProps extends Omit<ViewProps, 'children' | 'gap'> {
  children?: ReactNode
  /** Narrowest a cell gets, in px; the column count follows from it. Default `240`. */
  minChildWidth?: number
  /** Space between cells, across and down (token). Default `$4`. */
  gap?: SpaceTokens
  /** Most columns, however wide the grid gets. */
  maxColumns?: number
  onLayout?: (event: { nativeEvent: { layout: { width: number; height: number } } }) => void
}

/**
 * `grid-template-columns` for an AutoGrid. `auto-fill` keeps empty tracks, so
 * a lone card stays one column wide. `maxColumns` raises the narrowest cell to
 * a 1/n share of the row, so no more than n fit, and `min(…, 100%)` keeps one
 * column from overflowing a grid narrower than `minChildWidth`.
 */
export function autoGridTemplate(minChildWidth: number, gap: number, maxColumns?: number) {
  const min = `${Math.max(minChildWidth, 1)}px`
  const most = maxColumns !== undefined && maxColumns >= 1 ? Math.floor(maxColumns) : undefined
  const cell = most ? `max(${min}, calc((100% - ${(most - 1) * gap}px) / ${most}))` : min
  return `repeat(auto-fill, minmax(min(${cell}, 100%), 1fr))`
}

/**
 * Equal-width cells that fill the row: as many columns as fit at
 * `minChildWidth`, up to `maxColumns`. Web uses CSS grid, the one place Adv
 * UI does, because it is the only way to get the column count right on the
 * first paint (and in server-rendered HTML) without measuring.
 * AutoGrid.native.tsx measures instead.
 */
export const AutoGrid = forwardRef<TamaguiElement, AutoGridProps>(function AutoGrid(
  { minChildWidth = 240, gap = '$4', maxColumns, style, ...props },
  ref,
) {
  const template = autoGridTemplate(minChildWidth, spaceValue(gap), maxColumns)
  return (
    <View
      ref={ref}
      display={'grid' as ViewProps['display']}
      gap={gap}
      width="100%"
      {...props}
      style={{ gridTemplateColumns: template, ...(style as object | undefined) }}
    />
  )
})

import { Children, forwardRef, isValidElement, useState } from 'react'
import { type TamaguiElement, View } from 'tamagui'
import type { AutoGridProps } from './AutoGrid'
import { autoGridColumns, spaceValue } from './autoGridColumns'

/**
 * Native: React Native has no CSS grid, so the grid measures its width and
 * lays cells out like Grid does, a wrapping row of equal widths. Until the
 * first layout it renders one full-width column, so cells never flash at zero width.
 */
export const AutoGrid = forwardRef<TamaguiElement, AutoGridProps>(function AutoGrid(
  { children, minChildWidth = 240, gap = '$4', maxColumns, onLayout, ...props },
  ref,
) {
  const [width, setWidth] = useState(0)
  const space = spaceValue(gap)
  const columns = width ? autoGridColumns(width, minChildWidth, space, maxColumns) : 1
  // Whole pixels: Yoga rounds each cell, and widths that add up to a hair over
  // the row would push the last cell onto the next line.
  const cell = width ? Math.floor((width - (columns - 1) * space) / columns) : '100%'

  return (
    <View
      ref={ref}
      flexDirection="row"
      flexWrap="wrap"
      gap={gap}
      width="100%"
      onLayout={(event) => {
        setWidth(event.nativeEvent.layout.width)
        onLayout?.(event)
      }}
      {...props}
    >
      {Children.toArray(children).map((child, index) => (
        <View key={isValidElement(child) && child.key != null ? child.key : index} width={cell}>
          {child}
        </View>
      ))}
    </View>
  )
})

export type { AutoGridProps } from './AutoGrid'

import { type SpaceTokens, type Token, getTokenValue } from 'tamagui'

/**
 * How many columns at least `minChildWidth` wide fit in `width`, with `gap`
 * between them, capped by `maxColumns`, and never fewer than 1. It is the
 * count CSS grid's `repeat(auto-fill, minmax(…))` picks on web, so native
 * AutoGrids, which measure their width, get the same columns as web ones.
 */
export function autoGridColumns(
  width: number,
  minChildWidth: number,
  gap = 0,
  maxColumns?: number,
): number {
  const fit = Math.floor((width + gap) / (Math.max(minChildWidth, 1) + gap))
  const cap = maxColumns !== undefined && maxColumns >= 1 ? Math.floor(maxColumns) : Infinity
  const columns = Math.min(fit, cap)
  return Number.isFinite(columns) && columns > 1 ? columns : 1
}

/** A space token (or number) in px. */
export function spaceValue(gap: SpaceTokens | number): number {
  if (typeof gap === 'number') return gap
  return (getTokenValue(gap as Token, 'space') as number | undefined) ?? 0
}
